function WeatherInfoComponent({name, value}){

    return(
        <div className="InfoConteiner">
            <img className="InfoIcon" src="WeatherInfoIcons[name]" alt="name"/>
            <span className="InfoLabel">{name} {value}</span>

        </div>
    )
}

export default WeatherInfoComponent;
